import{_ as i,a as l,e as a,ar as c}from"./chunks/framework.CK3qJuPR.js";const p=JSON.parse('{"title":"CLI","description":"Linux常用命令","frontmatter":{"title":"CLI","description":"Linux常用命令","tags":["Linux","CLI"]},"headers":[],"relativePath":"cli/linux/cli.md","filePath":"cli/linux/cli.md","lastUpdated":1761045430000}'),d={name:"cli/linux/cli.md"};function o(r,e,t,n,s,h){return a(),l("div",null,[...e[0]||(e[0]=[c('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /vite-press/cli/linux/cli.md for this page in Markdown format</div><h1 id="linux-cli" tabindex="-1">Linux CLI <a class="header-anchor" href="#linux-cli" aria-label="Permalink to “Linux CLI”">​</a></h1><p>这些命令在前端开发中常用于文件和目录的操作、版本控制、进程管理、网络测试、包管理和构建工具等方面。使用这些命令可以进行代码管理、构建优化、调试和部署等任务。</p><blockquote><p>可以通过 <code>man</code> 命令查看每个命令的完整参数说明和用法。例如，使用 <code>man ls</code> 查看 <code>ls</code> 命令的详细说明。</p></blockquote><h2 id="文件和目录操作" tabindex="-1">文件和目录操作 <a class="header-anchor" href="#文件和目录操作" aria-label="Permalink to “文件和目录操作”">​</a></h2><ul><li><code>cd</code> - 切换当前目录。</li><li><code>ls</code> - 列出当前目录中的文件和文件夹。</li><li><code>mkdir</code> - 创建新的文件夹。</li><li><code>cp</code> - 复制文件或文件夹。</li><li><code>rm</code> - 删除文件或文件夹。</li><li><code>mv</code> - 移动文件或文件夹，或重命名。</li><li><code>cat</code> - 显示文本文件的内容。</li><li><code>grep</code> - 在文件中查找匹配的文本。</li></ul><h2 id="进程管理" tabindex="-1">进程管理 <a class="header-anchor" href="#进程管理" aria-label="Permalink to “进程管理”">​</a></h2><ul><li><code>ps</code> - 显示当前运行的进程列表。</li><li><code>kill</code> - 终止运行的进程。</li></ul><h2 id="网络相关" tabindex="-1">网络相关 <a class="header-anchor" href="#网络相关" aria-label="Permalink to “网络相关”">​</a></h2><ul><li><code>ping</code> - 测试与另一台计算机的网络连接。</li><li><code>ifconfig</code> - 显示网络接口的配置信息。</li><li><code>curl</code> - 发送 HTTP 请求并显示响应。</li></ul><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to “其他”">​</a></h2><ul><li><code>chmod</code> - 修改文件或目录的权限。</li><li><code>chown</code> - 修改文件或目录的所有者。</li><li><code>tar</code> - 创建和解压归档文件。</li><li><code>ssh</code> - 远程登录到另一台计算机。</li></ul>',12)])])}const m=i(d,[["render",o]]);export{p as __pageData,m as default};
